import React from 'react';
import { Types, parseData } from '@alifd/adaptor-helper';
import { Tab, Icon } from '@alifd/next';

export default {
    name: 'Tab',
    shape: ['pure', 'wrapped', 'text', 'capsule'],
    editor: (shape = 'pure') => {
        const props = [{
            name: 'size',
            type: Types.enum,
            options: ['medium', 'small'],
            default: 'medium'
        }, {
            name: 'closable',
            type: Types.bool,
            default: false
        }];

        if (['pure', 'wrapped', 'text'].indexOf(shape) !== -1) {
            props.push({
                name: 'overflow',
                label: 'Overflow Indicator',
                type: Types.enum,
                options: ['slide', 'dropdown'],
                default: 'slide'
            });
            props.push({
                name: 'width',
                type: Types.number,
                default: 480
            });
        }

        if (shape === 'wrapped') {
            props.splice(props.length - 2, 0, {
                name: 'position',
                type: Types.enum,
                options: ['top', 'left', 'right'],
                default: 'top'
            });
        }

        return {
            props,
            data: {
                active: true,
                disable: true,
                default: 'Tab 1\n*Tab 2\nTab 3'
            }
        };
    },
    adaptor: ({ shape, size, closable, overflow, width, position, style = {}, data, ...others }) => {
        const list = parseData(data, { parseContent: true });
        const activeKey = list.findIndex((item) => item.state === 'active');

        return (
            <Tab {...others} style={{ minWidth: style.width ? 0 : width, ...style }} activeKey={activeKey} shape={shape} size={size} excessMode={overflow} tabPosition={position}>
                {
                    list.map((item, index) => <Tab.Item key={index} title={item.value.map(({ type, value }, i) => type === 'icon' ? <Icon key={`icon_${i}`} type={value} /> : value)} closeable={closable} disabled={item.state === 'disabled'} />)
                }
            </Tab>
        );
    }
};

5.document_content:
# 可关闭选项卡

- order: 6

可关闭选项卡，可以通过在 `Tab.Item` 上设置 `closeable` 属性设置该选项卡是否可关闭。

:::lang=en-us
# Closeable

- order: 6

Creating closeable tabs by pass attribute `closeable` to `Tab.Item`.

:::

---

````jsx
import { Tab, Button, Icon } from '@alifd/next';

const panes = [
    { tab: 'Mail', key: 1, closeable: false },
    { tab: 'Message', key: 2, closeable: true },
    { tab: 'Setting', key: 3, closeable: true },
    { tab: 'Unread', key: 4, closeable: true }
];

class CloseableTab extends React.Component {

    constructor(props) {
        super(props);
        this.state = {
            panes: panes,
            activeKey: panes[0].key
        };
    }

    /*eslint-disable eqeqeq */
    remove(targetKey) {
        let activeKey = this.state.activeKey;
        const panes = [];
        this.state.panes.forEach(pane => {
            if (pane.key != targetKey) {
                panes.push(pane);
            }
        });

        if (targetKey == activeKey) {
            activeKey = panes[0].key;
        }
        this.setState({ panes, activeKey });
    }

    onClose = (targetKey) => {
        this.remove(targetKey);
    }

    onChange = (activeKey) => {
        this.setState({ activeKey });
    }

    addTabpane = () => {
        this.setState(prevState => {
            const { panes } = prevState;
            panes.push({ tab: 'new tab', key: Math.random(), closeable: true });
            return { panes };
        });
    }

    render() {
        const state = this.state;
        return (
            <div>
                <Button onClick={this.addTabpane} type="primary"><Icon type="add"/> New Tab</Button>

                <Tab
                    shape="wrapped"
                    activeKey={state.activeKey}
                    onChange={this.onChange}
                    onClose={this.onClose}
                    className="custom-tab">
                    {state.panes.map(item => <Tab.Item title={item.tab} key={item.key} closeable={item.closeable}>{item.tab} content</Tab.Item>)}
                </Tab>
            </div>
        );
    }
}

ReactDOM.render(<CloseableTab />, mountNode);
````

